mapper.update:
/* common.coco.insertCommonCoCoIssueReg*/ INSERT INTO KEP_PO_MNG ( BUYER, PO_NO, PO_SEQ, DS_SEQ, SEQ, PR_NO, PR_SEQ, AGENT, STATUS, TYPE, NOTICE_DATE, AGENT_REMARK, ADD_USER_ID, ADD_DATE, CHANGE_USER_ID, CHANGE_DATE ) ( SELECT BUYER, PO_NO, PO_SEQ, DS_SEQ, NEW_SEQ, PR_NO, PR_SEQ, AGENT, STATUS, TYPE, NOTICE_DATE, AGENT_REMARK, ADD_USER_ID, ADD_DATE, CHANGE_USER_ID, CHANGE_DATE FROM ( SELECT PO.BUYER, PO.PO_NO, PO.PO_SEQ, '000000' AS DS_SEQ, ( SELECT NVL(MAX(SEQ),0)+1 FROM KEP_PO_MNG MN WHERE MN.BUYER = PO.BUYER AND MN.PO_NO = PO.PO_NO AND MN.PO_SEQ = PO.PO_SEQ AND MN.DS_SEQ = '000000' ) AS NEW_SEQ, PO.PR_NO, PO.PR_SEQ, PH.AGENT, 'S' AS STATUS, 'C' AS TYPE, TO_CHAR(SYSDATE,'YYYYMMDD') AS NOTICE_DATE, #{st_remark} AS AGENT_REMARK, #{st_user_id} AS ADD_USER_ID, SYSDATE AS ADD_DATE, #{st_user_id} AS CHANGE_USER_ID, SYSDATE AS CHANGE_DATE FROM ICOMPODT PO, ICOMPOHD PH WHERE PO.BUYER = #{st_buyer} AND PO.PO_NO = #{st_po_no}
AND PO.PO_SEQ = #{st_po_seq}
AND PH.BUYER = PO.BUYER AND PH.PO_NO = PO.PO_NO ) )
